{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Chain TVL Data",
    "url": "http://localhost:7802",
    "operation": "add",
    "widgets_json": {
      "chain_flows_table": {
        "name": "Chain Flows Table",
        "description": "Net chain flows and fee share.",
        "type": "table",
        "endpoint": "/chain-flows-table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "params": [
          {
            "paramName": "chain",
            "type": "text",
            "label": "Chain",
            "value": "Ethereum",
            "description": "Chain Flows Table focus field."
          }
        ],
        "data": {
          "defaultSymbol": "chain",
          "table": {
            "columnsDefs": [
              {
                "field": "as_of",
                "headerName": "As Of",
                "cellDataType": "dateString"
              },
              {
                "field": "chain",
                "headerName": "Chain",
                "cellDataType": "text"
              },
              {
                "field": "fee_pct",
                "headerName": "Fee Pct",
                "cellDataType": "number",
                "formatterFn": "percent"
              },
              {
                "field": "net_flow_usd",
                "headerName": "Net Flow USD",
                "cellDataType": "number"
              }
            ]
          }
        }
      },
      "gas_metric": {
        "name": "Gas Now",
        "description": "Current gas price snapshot.",
        "type": "metric",
        "endpoint": "/gas-now",
        "gridData": {
          "w": 5,
          "h": 4
        }
      }
    }
  }
}

